import sys
import bisect as bi
import collections as cc
I = lambda : list(map(int, input().split()))
for tc in range(int(input())):
	(n, k) = I()
	s = list(input())
	if s.count('W') == 0:
		now = min(k, n)
		print(max(0, 1 + 2 * (now - 1)))
		continue
	i = 0
	gap = []
	for i in range(n):
		if s[i] == 'W':
			gap.append(i)
	ne = []
	for i in range(len(gap) - 1):
		ne.append([gap[i], gap[i + 1], gap[i + 1] - gap[i] - 1])
	ne.sort(key=lambda x: x[2])
	for i in ne:
		now = i[0] + 1
		while now < i[1] and k:
			s[now] = 'W'
			now += 1
			k -= 1
		if not k:
			break
	temp = []
	if s[0] != 'W':
		temp.append([-1, gap[0], gap[0] - -1 - 1])
	if s[-1] != 'W':
		temp.append([gap[-1], n, n - gap[-1] - 1])
	temp.sort(key=lambda x: x[2])
	for i in temp:
		if i[0] == -1:
			now = i[1] - 1
			while now >= 0 and k:
				k -= 1
				s[now] = 'W'
				now -= 1
		else:
			now = i[0] + 1
			while now < i[1] and k:
				s[now] = 'W'
				k -= 1
				now += 1
		if not k:
			break
	f = 0
	cnt = 0
	ans = 0
	for i in range(n):
		if not f and s[i] == 'W':
			f = 1
			ans += 1
		elif f and s[i] == 'W':
			ans += 2
		else:
			f = 0
	print(ans)
